class Solution {
    private static final int[][] DIRS = new int[][]{{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public boolean exist(char[][] board, String word) {
        int m = board.length;
        int n = board[0].length;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (backtrack(i, j, board, word, 0)) {
                    return true;
                }
            }
        }
        return false;
    }

    public boolean backtrack(int r, int c, char[][] board, String word, int index){
        if (index >= word.length()){
            return true;
        }

        int m = board.length;
        int n = board[0].length;
        if (r < 0 || c < 0 || r >= m || c >= n) {
            return false;
        }

        // Candidates are up down left right
        // Prune candidates that are not the next word
        if (board[r][c] == word.charAt(index)) {
            // Add valid candidate
            board[r][c] = '#';

            boolean ret = false;
            // Explore
            ret = backtrack(r + 1, c, board, word, index + 1)
                || backtrack(r - 1, c, board, word, index + 1)
                || backtrack(r, c + 1, board, word, index + 1) 
                || backtrack(r, c - 1, board, word, index + 1);
            // Clean up candidate
            board[r][c] = word.charAt(index);
            return ret;
        }
        return false;
    }
}

class Solution {
    public String alienOrder(String[] words) {
        // Step 0: Create data structures and find all unique letters.
        Map<Character, List<Character>> adjList = new HashMap<>();
        Map<Character, Integer> indegrees = new HashMap<Character, Integer>();

        for (String word : words) {
            for (char c : word.toCharArray()) {
                indegrees.put(c, 0);
                adjList.put(c, new ArrayList<>());
            }
        }

        // Find edges
        for (int i = 0; i < words.length -1; i++) {
            String word1 = words[i];
            String word2 = words[i+1];

            if (word1.length() > word2.length() && word1.startsWith(word2)){
                return "";
            }
            for (int j = 0; j < Math.min(word1.length(), word2.length()); j++) {
                if (word1.charAt(j) != word2.charAt(j) ) {
                    adjList.get(word1.charAt(j)).add(word2.charAt(j));
                    indegrees.put(word2.charAt(j), indegrees.get(word2.charAt(j)) + 1);
                    break;
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        Deque<Character> queue = new ArrayDeque();

        System.out.println(indegrees);
        for (Character c : indegrees.keySet()) {
            if (indegrees.get(c).equals(0)) {
                queue.offer(c);
            }
        }

        while (!queue.isEmpty()) {
            Character c = queue.poll();
            sb.append(c);

            for (Character neighbor: adjList.get(c)) {
                indegrees.put(neighbor, indegrees.get(neighbor) - 1);
                if (indegrees.get(neighbor).equals(0)) {
                    queue.offer(neighbor);
                }
            }
        }
        if (sb.length() < indegrees.size()) {
            return "";
        }
        return sb.toString();
    }
}

class UnionFind {
    int[] root;

    public UnionFind(int size) {
        root = new int[size];
        for (int i = 0; i < size; i++) {
            root[i] = i;
        }
    }

    public int find(int n) {
        return root[n];
    }

    public boolean union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA == rootB) {
            return false;
        }
        if (rootA != rootB) {
            for (int i = 0; i < root.length; i++){
                // Replace all of rootB with rootA;
                if (root[i] == rootB) {
                    root[i] = rootA;
                }
            }
        }

        return true;
    }

    public boolean connected(int a, int b) {
        return find(a) == find(b);
    }
}

class Solution {
    public boolean validTree(int n, int[][] edges) {
        // Condition 1: The graph must contain n - 1 edges.
        if (edges.length != n - 1) return false;

        UnionFind union = new UnionFind(n);

        for (int[] edge: edges) {
            if(union.connected(edge[0], edge[1])) {
                return false;
            }
            union.union(edge[0], edge[1]);
        }

        return true;
    }
}

class Solution {
    public int nearestExit(char[][] maze, int[] entrance) {

        Deque<int[]> q = new ArrayDeque();

        boolean[][] visited = new boolean[maze.length][maze[0].length];


        q.offer(new int[] {entrance[0], entrance[1], 0});

        visited[entrance[0]][entrance[1]] = true;
        int[][] dirs = { {0,1}, {0,-1}, {1,0}, {-1,0} };

        while (!q.isEmpty()) {
            int[] curr = q.poll();

            for (int[] dir : dirs) {
                int i = curr[0] + dir[0];
                int j = curr[1] + dir[1];

                if (i < 0 || j < 0 || i >= maze.length || j >= maze[0].length || visited[i][j] || maze[i][j] == '+') {
                    continue;
                }

                if (isExit(i, j, maze)) {
                    return curr[2] + 1;
                }

                visited[i][j] = true;
                q.offer(new int[] {i, j, curr[2] + 1});
            }    
        }

        return -1;
    }

    public boolean isExit(int nextRow, int nextCol, char[][] maze) {
        return (nextRow == 0 || nextRow == maze.length - 1 || nextCol == 0 || nextCol == maze[0].length - 1);
    }
}

class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {

        Map<Integer, List<Integer>> adj = new HashMap();

        for (int i = 0; i < numCourses; i++) {
            adj.computeIfAbsent(i, k -> new ArrayList());
        }

        for (int i = 0; i < prerequisites.length; i++) {
            int[] prereq = prerequisites[i];
            adj.get(prereq[1]).add(prereq[0]);
        }

        boolean[] checked = new boolean[numCourses];
        boolean[] path = new boolean[numCourses];
        for (int node: adj.keySet()) {
            if (dfs(adj, node, path, checked)) {
                return false;
            }
        }
        return true;
    }

    private boolean dfs(Map<Integer, List<Integer>> adj, int node, boolean[] path, boolean[] checked) {
        // bottom cases
        if (checked[node])
            // this node has been checked, no cycle would be formed with this node.
            return false;

        if (path[node]) {
            return true;
        }

        if (!adj.containsKey(node)) {
            return false;
        }
        path[node] = true;

        boolean ret = false;

        for(int neighbor : adj.get(node)) {
            ret = dfs(adj, neighbor, path, checked);
            if (ret) {
                break;
            }
        }
        path[node] = false;
        checked[node] = true;
        return ret;
    }
}

class Solution {
    public int maxArea(int[] height) {
        int left = 0;
        int right = height.length - 1;

        int maxArea = 0;
        while (left < right){
            int width = right - left;
            int length = Math.min(height[left], height[right]);
            int currentArea = width * length;
            maxArea = Math.max(currentArea, maxArea);

            if (height[left] > height[right]) {
                right--;
            } else {
                left++;
            }
        }

        return maxArea;
    }
}

class Solution {
    public int sumSubarrayMins(int[] arr) {
        int MOD = 1000000007;

        Stack<Integer> stack = new Stack<>();
        long sumOfMinimums = 0;

        // building monotonically increasing stack
        for (int i = 0; i <= arr.length; i++) {

            // when i reaches the array length, it is an indication that
            // all the elements have been processed, and the remaining
            // elements in the stack should now be popped out.

            while (!stack.empty() && (i == arr.length || arr[stack.peek()] >= arr[i])) {

                // Notice the sign ">=", This ensures that no contribution
                // is counted twice. rightBoundary takes equal or smaller 
                // elements into account while leftBoundary takes only the
                // strictly smaller elements into account

                int mid = stack.pop();
                int leftBoundary = stack.empty() ? -1 : stack.peek();
                int rightBoundary = i;

                // count of subarrays where mid is the minimum element
                long count = (mid - leftBoundary) * (rightBoundary - mid) % MOD;

                sumOfMinimums += (count * arr[mid]) % MOD;
                sumOfMinimums %= MOD;
            }
            stack.push(i);
        }

        return (int) (sumOfMinimums);
    }
}

class Solution {
    int[] memo;
    public int jobScheduling(int[] startTime, int[] endTime, int[] profit) {

        List<int[]> jobs = new ArrayList();
        memo = new int[startTime.length];
        Arrays.fill(memo, -1);

        for (int i = 0; i < startTime.length; i++) {
            jobs.add(new int[] {startTime[i], endTime[i], profit[i]});
        }

        // Arrays.sort(list, (a, b)-> a[0]- b[0]);
        jobs.sort((a1,a2) -> a1[0] - a2[0]);

        jobs.forEach((l)->{
            System.out.println(Arrays.toString(l));
        });

        // binary search will be used in startTime so store it as separate list
        for (int i = 0; i < profit.length; i++) {
            startTime[i] = jobs.get(i)[0];
        }

        return findMaxProfit(jobs, 0);
    }

    private int findMaxProfit(List<int[]> jobs, int position) {
        // 0 profit if we have already iterated over all the jobs
        if (position == jobs.size()) {
            return 0;
        }
        if(memo[position]!=-1)
            return memo[position];

        int nextIndex = -1;

        for (int i = position+1; i < jobs.size(); i++) {
            if(jobs.get(i)[0] >= jobs.get(position)[1]) {
                nextIndex = i;
                break;
            }
        }

        int include = jobs.get(position)[2];
        if (nextIndex != -1) {
            include += findMaxProfit(jobs, nextIndex);
        }

        int exclude = findMaxProfit(jobs, position + 1);
        int maxProfit = Math.max(include, exclude);

        memo[position] = maxProfit;
        return memo[position];
    }
}

