class Solution {
    public String frequencySort(String s) {

        Map<Character, Integer> sMap = new HashMap();

        for (char c : s.toCharArray()) {
            sMap.put(c, sMap.getOrDefault(c, 0) + 1);
        }

        List<Character> characters = new ArrayList<>(sMap.keySet());        
        Collections.sort(characters, (a, b) -> sMap.get(b) - sMap.get(a));

        StringBuilder sb = new StringBuilder();
        for (char c: characters) {
            for(int i = 0; i < sMap.get(c); i++) {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}

class Solution {
    public boolean closeStrings(String word1, String word2) {
        if (word1.length() != word2.length()) {
            return false;
        }

        Map<Character, Integer> word1Map = new HashMap();
        Map<Character, Integer> word2Map = new HashMap();

        for (char c : word1.toCharArray()) {
            word1Map.put(c, word1Map.getOrDefault(c, 0) + 1);
        }

        for (char c : word2.toCharArray()) {
            word2Map.put(c, word2Map.getOrDefault(c, 0) + 1);
        }

        if (!word1Map.keySet().equals(word2Map.keySet())) {
            return false;
        }

        List<Integer> word1FrequencyList = new ArrayList<>(word1Map.values());
        List<Integer> word2FrequencyList = new ArrayList<>(word2Map.values());

        Collections.sort(word1FrequencyList);
        Collections.sort(word2FrequencyList);
        return word1FrequencyList.equals(word2FrequencyList);
    }
}

class Solution {
    public boolean halvesAreAlike(String s) {
        String vowels = "aeiouAEIOU";
        int count = 0;
        int n = s.length();
        for (int i = 0; i < n / 2; i++){
            for (char c : vowels.toCharArray()) {
                if (s.charAt(i) == c) {
                    count++;
                }
            }
        }

        for (int i = n / 2; i < n; i++){
            for (char c : vowels.toCharArray()) {
                if (s.charAt(i) == c) {
                    count--;
                }
            }
        }

        return count == 0;
    }
}

class Solution {
    public int rob(int[] nums) {
        if (nums.length == 0) return 0;
        if (nums.length == 1) return nums[0];

        return Math.max(
            robHelper(nums, 0, nums.length - 2),
            robHelper(nums, 1, nums.length - 1)
        );
    }

    public int robHelper(int[] nums, int start, int end) {
        int rob1 = 0;
        int rob2 = 0;
        for (int i = start; i <= end; i++) {
            int temp = Math.max(rob1 + nums[i], rob2);
            rob1 = rob2;
            rob2 = temp;
        }
        return rob2;
    }
}

class Solution {
    public int findMin(int[] nums) {

        int l = 0;
        int r = nums.length -1;

        while (l < r) {
            int mid = (l + r) >>> 1;
            if (nums[mid] < nums[r]) {
                r = mid;
            } else {
                l = mid + 1;
            }
        }

        return nums[l];

    }
}

